const assertValidLevel = level => {
	if (!Number.isSafeInteger(level) || level < 0 || level > 3) {
		throw new Error('The `level` should be an integer from 0 to 3');
	}
};

const applyOptions = (object, options = {}) => {
	if (options.level !== undefined) {
		assertValidLevel(options.level);
	}

	// Detect level if not set manually. Written under the symbol rather than through `level`, as the prototype carrying that accessor is not installed until after this runs.
	const colorLevel = stdoutColor ? stdoutColor.level : 0;
	object[LEVEL] = options.level === undefined ? colorLevel : options.level;
};

set(level) {
	assertValidLevel(level);
	this[LEVEL] = level;
},

test('assigning `level` is validated', t => {
	const instance = new Chalk({level: 1});

	// Unlike the option, `undefined` is not a way to ask for detection here
	for (const level of [10, -1, 1.5, ' 1', undefined]) {
		t.throws(() => {
			instance.level = level;
		}, {message: /should be an integer from 0 to 3/v}, `level: ${level}`);
	}

	// A style in the chain writes through to the instance, so it is validated too
	t.throws(() => {
		instance.red.level = 10;
	}, {message: /should be an integer from 0 to 3/v});

	t.is(instance.level, 1);

	instance.level = 0;
	t.is(instance.level, 0);
	t.is(instance.red('foo'), 'foo');
});

test('the `level` option should be a number from 0 to 3', t => {
	/* eslint-disable no-new -- Ignore */
	t.throws(() => {
		new Chalk({level: 10});
	}, {message: /should be an integer from 0 to 3/v});

	t.throws(() => {
		new Chalk({level: -1});
	}, {message: /should be an integer from 0 to 3/v});
	/* eslint-enable no-new */
});

test('a `FORCE_COLOR` above 3 is clamped to 3', async t => {
	t.is(await detectLevel({FORCE_COLOR: '4', TERM: 'xterm-256color'}), '3');
});

test('propagate enable/disable changes from child colors', t => {
	const oldLevel = chalk.level;
	chalk.level = 1;
	const {red} = chalk;
	t.is(red.level, 1);
	t.is(chalk.level, 1);
	red.level = 0;
	t.is(red.level, 0);
	t.is(chalk.level, 0);
	chalk.level = 1;
	t.is(red.level, 1);
	t.is(chalk.level, 1);
	chalk.level = oldLevel;
});

test('enable/disable colors based on overall chalk .level property, not individual instances', t => {
	const oldLevel = chalk.level;
	chalk.level = 1;
	const {red} = chalk;
	t.is(red.level, 1);
	chalk.level = 0;
	t.is(red.level, chalk.level);
	chalk.level = oldLevel;
});

test('`FORCE_COLOR=2` is an exact level, not a minimum', async t => {
	t.is(await detectLevel({FORCE_COLOR: '2', COLORTERM: 'truecolor'}), '2');
});

test('visible: normal output when level > 0', t => {
	const instance = new Chalk({level: 3});
	t.is(instance.visible.red('foo'), '\u{1B}[31mfoo\u{1B}[39m');
