function disable() {
	const namespaces = [
		...createDebug.names,
		...createDebug.skips.map(namespace => '-' + namespace)
	].join(',');
	createDebug.enable('');
	return namespaces;
}

it('handle names, skips, and wildcards', () => {
	debug.enable('test,abc*,-abc');
	const namespaces = debug.disable();
	assert.deepStrictEqual(namespaces, 'test,abc*,-abc');
