)
def test_run_interpolation_respects_override(
    tmp_path, option, existing_value, expected
):
    (tmp_path / ".env").write_text(
        "DOTENV_TEST_BASE=file\nDOTENV_TEST_DERIVED=${DOTENV_TEST_BASE}/suffix\n"
