	const chalkBlueBgRed = chalk.blue.bgRed;
	const chalkBlueBgRedBold = chalk.blue.bgRed.bold;

	const blueStyledString = 'the fox jumps' + chalk.blue('over the lazy dog') + '!';

	bench('1 style', () => {
		chalk.red('the fox jumps over the lazy dog');
	});

