test('when negated and default string then value is default', () => {
  // Bit tricky thinking about what default means for a negated option, but treat as with other options.
  const program = new Command();
  program.option('--no-colour', 'description', 'RGB');
  program.parse([], { from: 'user' });
  assert.equal(program.opts().colour, 'RGB');
});

test('when negated and default string then value is default', () => {
  // Bit tricky thinking about what default means for a negated option, but treat as with other options.
  const program = new Command();
  program.addOption(new Option('--no-colour').default('RGB'));
  program.parse([], { from: 'user' });
  assert.equal(program.opts().colour, 'RGB');
});

test('when negated and default string then value is false', () => {
  // Bit tricky thinking about what default means for a negated option, but treat as with other options.
  const program = new Command();
  program.option('--no-colour', 'description', 'RGB');
  program.parse(['--no-colour'], { from: 'user' });
  assert.equal(program.opts().colour, false);
});

test('when program has yes/no flag specified negated then false', () => {
  const program = new commander.Command();
  program
    .requiredOption('--cheese <type>', 'cheese type')
    .option('--no-cheese', 'no cheese thanks');
  program.parse(['node', 'test', '--no-cheese']);
  assert.equal(program.opts().cheese, false);
});

test('when lone negative then default value is true', () => {
  const program = new commander.Command();
  program.option('--no-pepper', 'remove pepper');
  program.parse([], { from: 'user' });
  assert.equal(program.opts().pepper, true);
});

test('when boolean combo and negative second then no implicit default', () => {
  const program = new commander.Command();
  program
    .option('--pepper', 'pepper only')
    .option('--no-pepper', 'remove pepper');
  program.parse([], { from: 'user' });
  assert.equal(program.opts().pepper, undefined);
});

test('when boolean combo and negative second with explicit default then get explicit default', () => {
  // Prior to Commander 15, negative second would ignore implicit and explicit default value.
  // Simpler rule now and the special default behaviour is for lone negative only. Add test since
  // intentional change of behaviour for unlikely edge case.
  const program = new commander.Command();
  program
    .option('--pepper', 'pepper only')
    .option('--no-pepper', 'remove pepper', 'plain');
  program.parse([], { from: 'user' });
  assert.equal(program.opts().pepper, 'plain');
});

test('when boolean combo and negative first then no implicit default', () => {
  // New behaviour in Commander 15, now only lone negative gets implicit default of true.
  const program = new commander.Command();
  program
    .option('--no-pepper', 'remove pepper')
    .option('--pepper', 'pepper only');
  program.parse([], { from: 'user' });
  assert.equal(program.opts().pepper, undefined);
});

test('when negative option then value is false', () => {
  const program = createPepperProgram();
  program.parse(['node', 'test', '--no-pepper']);
  assert.equal(program.opts().pepper, false);
});

test('when program has mandatory-yes/mandatory-no flag specified with flag then true', () => {
  const program = new commander.Command();
  program
    .requiredOption('--cheese', 'cheese type')
    .requiredOption('--no-cheese', 'no cheese thanks');
  program.parse(['node', 'test', '--cheese']);
  assert.equal(program.opts().cheese, true);
});

test('when program has mandatory-yes/no flag specified with flag then true', () => {
  const program = new commander.Command();
  program
    .requiredOption('--cheese', 'cheese type')
    .option('--no-cheese', 'no cheese thanks');
  program.parse(['node', 'test', '--cheese']);
  assert.equal(program.opts().cheese, true);
});

test('when program has value/no flag specified with value then specified value', () => {
  const program = new commander.Command();
  program
    .requiredOption('--cheese <type>', 'cheese type')
    .requiredOption('--no-cheese', 'no cheese thanks');
  program.parse(['node', 'test', '--cheese', 'blue']);
  assert.equal(program.opts().cheese, 'blue');
});

test('when program has yes/no not specified then error', () => {
  const program = createTestCommand();
  program
    .requiredOption('--cheese', 'cheese type')
    .option('--no-cheese', 'no cheese thanks');

  assert.throws(() => {
    program.parse(['node', 'test']);
  });
});

