export interface Options {
	/**
	Specify the color support for Chalk.

	By default, color support is automatically detected based on the environment.

	Levels:
	- `0` - All colors disabled.
	- `1` - Basic 16 colors support.
	- `2` - ANSI 256 colors support.
	- `3` - Truecolor 16 million colors support.

	Omit this option, or pass `undefined`, to have the level detected instead.

	@throws If the value is neither `undefined` nor an integer from 0 to 3.
	*/
	readonly level?: ColorSupportLevel | undefined;
}

test('don\'t emit color codes if level is 0', t => {
	t.is(new Chalk({level: 0}).hex('#FF0000')('hello'), 'hello');
	t.is(new Chalk({level: 0}).bgHex('#FF0000')('hello'), 'hello');
	t.is(new Chalk({level: 0}).ansi256(196)('hello'), 'hello');
	t.is(new Chalk({level: 0}).bgAnsi256(196)('hello'), 'hello');
	t.is(new Chalk({level: 0}).underlineHex('#FF0000')('hello'), 'hello');
	t.is(new Chalk({level: 0}).underlineAnsi256(196)('hello'), 'hello');
	t.is(new Chalk({level: 0}).underlineRed('hello'), 'hello');
	t.is(new Chalk({level: 0}).underlineCurly('hello'), 'hello');
});

test('enable/disable colors based on overall chalk .level property, not individual instances', t => {
	const oldLevel = chalk.level;
	chalk.level = 1;
	const {red} = chalk;
	t.is(red.level, 1);
	chalk.level = 0;
	t.is(red.level, chalk.level);
	chalk.level = oldLevel;
});

test('don\'t output colors when manually disabled', t => {
	const oldLevel = chalk.level;
	chalk.level = 0;
	t.is(chalk.red('foo'), 'foo');
	chalk.level = oldLevel;
});

test('an omitted `level` option is detected rather than rejected', t => {
	t.is(new Chalk({level: undefined}).level, new Chalk().level);
});

test('propagate enable/disable changes from child colors', t => {
	const oldLevel = chalk.level;
	chalk.level = 1;
	const {red} = chalk;
	t.is(red.level, 1);
	t.is(chalk.level, 1);
	red.level = 0;
	t.is(red.level, 0);
	t.is(chalk.level, 0);
	chalk.level = 1;
	t.is(red.level, 1);
	t.is(chalk.level, 1);
	chalk.level = oldLevel;
});

test('`FORCE_COLOR=0` disables color', async t => {
	t.is(await detectLevel({FORCE_COLOR: '0', COLORTERM: 'truecolor'}), '0');
});

test('create an isolated context where colors can be disabled (by level)', t => {
	const instance = new Chalk({level: 0});
	t.is(instance.red('foo'), 'foo');
	t.is(chalk.red('foo'), '\u{1B}[31mfoo\u{1B}[39m');
	instance.level = 2;
	t.is(instance.red('foo'), '\u{1B}[31mfoo\u{1B}[39m');
});

const builder = (...arguments_) => {
	if (arguments_.length === 1) {
		// eslint-disable-next-line no-implicit-coercion
		return applyStyle(builder, '' + arguments_[0]);
	}

	if (arguments_.length === 2) {
		// The template literal matches `Array#join` coercion (`null` and `undefined` become empty, objects use `toString`) while being faster.
		return applyStyle(builder, `${arguments_[0] ?? ''} ${arguments_[1] ?? ''}`);
	}

	return applyStyle(builder, arguments_.join(' '));
};

test('colors can be forced by using chalk.level', t => {
	chalk.level = 1;
	t.is(chalk.green('hello'), '\u{1B}[32mhello\u{1B}[39m');
});

test('the `level` option should be a number from 0 to 3', t => {
	/* eslint-disable no-new -- Ignore */
	t.throws(() => {
		new Chalk({level: 10});
	}, {message: /should be an integer from 0 to 3/v});

	t.throws(() => {
		new Chalk({level: -1});
	}, {message: /should be an integer from 0 to 3/v});
	/* eslint-enable no-new */
});

